window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bdc0fe4542be941a"]={"versions": [{"id": "FIG-bdc0fe4542be941a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Hardware-Sensor-/Aktorelementen und deren Port-Anbindungen im Kontext des AUTOSAR ECU Resource Templates (Hardware-Beschreibungsebene).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert Spezialisierungen und Assoziationen rund um Hardware-Elemente und Hardware-Ports:</p>\n<ul class=\"fig-list\"><li><strong><code>SensorActuatorHW</code></strong> (Stereotyp/Spezialisierung von <code>HWElement</code>, kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Attribute: <code>type: String</code>, <code>accuracy: Float</code>, <code>resolution: Float [0..1]</code>.\n</li><li>Komposition zu <code>TimeRange</code> über die Rolle <code>+cycleTime</code> mit Multiplizität <code>0..1</code>.\n</li><li>Abhängigkeiten / Port-Verknüpfungen (gestrichelte Pfeile):\n<ul class=\"fig-list\"><li>Abhängigkeit zu <code>HWPort</code> mit der Beschriftung <code>Technical Signal HW Port</code>.\n</li><li>Abhängigkeit zu <code>PeripheralHWPort</code>.\n</li><li>Abhängigkeit zu <code>CommunicationHWPort</code>.\n</li></ul>\n</li><li>Generalisierungsbasis für die konkreten Hardware-Klassen:\n<ul class=\"fig-list\"><li><code>ActuatorHW</code>\n</li><li><code>SensorHW</code>\n</li><li><code>DisplayHW</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>ActuatorHW</code></strong>:\n<ul class=\"fig-list\"><li>Erbt von <code>SensorActuatorHW</code>.\n</li><li>Besitzt eine gerichtete Abhängigkeit (gestrichelter Pfeil) zu <code>PowerDriverHWPort</code>.\n</li></ul>\n</li><li><strong><code>TimeRange</code></strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>min: Float [0..1]</code>, <code>max: Float</code>, <code>typical: Float [0..1]</code>.\n</li></ul>\n</li><li><strong>Port-Hierarchie (<code>HWPort</code>, erbt von <code>Identifiable</code>):</strong>\n<ul class=\"fig-list\"><li><code>HWPort</code> fungiert als Basisklasse für hardwarebezogene Schnittstellen.\n</li><li><code>PowerDriverHWPort</code> erbt direkt von <code>HWPort</code>.\n</li><li><code>PeripheralHWPort</code> erbt direkt von <code>HWPort</code>.\n</li><li><code>CommunicationHWPort</code> erbt von <code>PeripheralHWPort</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung von Laufzeit- oder Sequenzverhalten. Die Spezifikation beschreibt Deklarationsstrukturen zur statischen Beschreibung von Hardware-Ressourcen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt verbindliche Metaklassen für die Beschreibung von Sensor-, Aktor- und Display-Hardwarekomponenten fest:</p>\n<ul class=\"fig-list\"><li><code>SensorActuatorHW</code> erfordert zwingend Angaben zu <code>type</code> und <code>accuracy</code>, während <code>resolution</code> optional ist.\n</li><li>Die Zykluszeit (<code>+cycleTime</code>) kann optional über eine <code>TimeRange</code> strukturiert mit Minimal-, Maximal- und typischem Wert angegeben werden, wobei <code>max</code> obligatorisch ist.\n</li><li>Spezifische Hardware-Ports (<code>PowerDriverHWPort</code>, <code>PeripheralHWPort</code>, <code>CommunicationHWPort</code>) müssen den typisierten Verbindungsanforderungen von Sensoren und Aktoren entsprechen; <code>ActuatorHW</code> bindet explizit an Leistungs-Treiberports (<code>PowerDriverHWPort</code>) an.\n</li></ul>"}, {"id": "FIG-9fe16b23eb5d07a5", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Hardware-Sensor-/Aktorelementen und deren Port-Anbindungen im Kontext des AUTOSAR ECU Resource Templates (Hardware-Beschreibungsebene).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert Spezialisierungen und Assoziationen rund um Hardware-Elemente und Hardware-Ports:</p>\n<ul class=\"fig-list\"><li><strong><code>SensorActuatorHW</code></strong> (Stereotyp/Spezialisierung von <code>HWElement</code>, kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Attribute: <code>type: String</code>, <code>accuracy: Float</code>, <code>resolution: Float [0..1]</code>.\n</li><li>Komposition zu <code>TimeRange</code> über die Rolle <code>+cycleTime</code> mit Multiplizität <code>0..1</code>.\n</li><li>Abhängigkeiten / Port-Verknüpfungen (gestrichelte Pfeile):\n<ul class=\"fig-list\"><li>Abhängigkeit zu <code>HWPort</code> mit der Beschriftung <code>Technical Signal HW Port</code>.\n</li><li>Abhängigkeit zu <code>PeripheralHWPort</code>.\n</li><li>Abhängigkeit zu <code>CommunicationHWPort</code>.\n</li></ul>\n</li><li>Generalisierungsbasis für die konkreten Hardware-Klassen:\n<ul class=\"fig-list\"><li><code>ActuatorHW</code>\n</li><li><code>SensorHW</code>\n</li><li><code>DisplayHW</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>ActuatorHW</code></strong>:\n<ul class=\"fig-list\"><li>Erbt von <code>SensorActuatorHW</code>.\n</li><li>Besitzt eine gerichtete Abhängigkeit (gestrichelter Pfeil) zu <code>PowerDriverHWPort</code>.\n</li></ul>\n</li><li><strong><code>TimeRange</code></strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>min: Float [0..1]</code>, <code>max: Float</code>, <code>typical: Float [0..1]</code>.\n</li></ul>\n</li><li><strong>Port-Hierarchie (<code>HWPort</code>, erbt von <code>Identifiable</code>):</strong>\n<ul class=\"fig-list\"><li><code>HWPort</code> fungiert als Basisklasse für hardwarebezogene Schnittstellen.\n</li><li><code>PowerDriverHWPort</code> erbt direkt von <code>HWPort</code>.\n</li><li><code>PeripheralHWPort</code> erbt direkt von <code>HWPort</code>.\n</li><li><code>CommunicationHWPort</code> erbt von <code>PeripheralHWPort</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung von Laufzeit- oder Sequenzverhalten. Die Spezifikation beschreibt Deklarationsstrukturen zur statischen Beschreibung von Hardware-Ressourcen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt verbindliche Metaklassen für die Beschreibung von Sensor-, Aktor- und Display-Hardwarekomponenten fest:</p>\n<ul class=\"fig-list\"><li><code>SensorActuatorHW</code> erfordert zwingend Angaben zu <code>type</code> und <code>accuracy</code>, während <code>resolution</code> optional ist.\n</li><li>Die Zykluszeit (<code>+cycleTime</code>) kann optional über eine <code>TimeRange</code> strukturiert mit Minimal-, Maximal- und typischem Wert angegeben werden, wobei <code>max</code> obligatorisch ist.\n</li><li>Spezifische Hardware-Ports (<code>PowerDriverHWPort</code>, <code>PeripheralHWPort</code>, <code>CommunicationHWPort</code>) müssen den typisierten Verbindungsanforderungen von Sensoren und Aktoren entsprechen; <code>ActuatorHW</code> bindet explizit an Leistungs-Treiberports (<code>PowerDriverHWPort</code>) an.\n</li></ul>"}], "trans": [{"from": "FIG-bdc0fe4542be941a", "to": "FIG-9fe16b23eb5d07a5", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
